using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.NTF.Notificaciones;using GraphApi.Services.NTF.Notificaciones;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.NTF.Notificaciones{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Notificaciones: creación, actualización y eliminación.")]    public class NotificacionesMutation    {        [Authorize]        [GraphQLName("createNotificaciones")]        [GraphQLDescription("Crea un nuevo Notificacione usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadNotificaciones> CreateNotificacionesAsync(            [GraphQLDescription("Datos necesarios para crear el Notificacione.")]            clCreateNotificaciones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Notificacione.")]            INotificacionesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateNotificaciones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateNotificaciones")]        [GraphQLDescription("Actualiza los campos especificados de un Notificacione existente.")]        public async Task<clReadNotificaciones?> UpdateNotificacionesAsync(            [GraphQLDescription("Datos del Notificacione a actualizar.")]            clUpdateNotificaciones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Notificacione.")]            INotificacionesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateNotificaciones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteNotificaciones")]        [GraphQLDescription("Elimina un Notificacione por su ID.")]        public async Task<bool> delNotificacionesAsync(            [GraphQLDescription("ID del Notificacione a eliminar.")]            int nNotificacionesID,            [Service]            [GraphQLDescription("Servicio para operaciones de Notificacione.")]            INotificacionesService objService        )        {            return await objService.DeleteNotificaciones(nNotificacionesID);        }    }}